CREATE OR REPLACE FUNCTION public.consume_rate_limit(p_key text, p_limit integer, p_window interval)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  insert into public.rate_limits (key, window_start, count)
  values (p_key, now(), 1)
  on conflict (key) do update
    set
      -- Reset the window if the old one has elapsed, otherwise increment.
      window_start = case
        when public.rate_limits.window_start < now() - p_window then now()
        else public.rate_limits.window_start
      end,
      count = case
        when public.rate_limits.window_start < now() - p_window then 1
        else public.rate_limits.count + 1
      end
  returning count into v_count;

  return v_count <= p_limit;
end;
$function$;

